import { readFileSync } from 'node:fs';
import { inflateSync } from 'node:zlib';

const buf = readFileSync('/workspace/dataset/test2_executable');

// --- locate PyInstaller CArchive cookie ---
const MAGIC = Buffer.from([0x4d, 0x45, 0x49, 0x0c, 0x0b, 0x0a, 0x0b, 0x0e]);
let cookiePos = -1;
for (let i = buf.length - MAGIC.length; i >= 0; i--) {
  let ok = true;
  for (let j = 0; j < MAGIC.length; j++) if (buf[i + j] !== MAGIC[j]) { ok = false; break; }
  if (ok) { cookiePos = i; break; }
}
if (cookiePos < 0) throw new Error('cookie not found');
const pkgLen = buf.readUInt32BE(cookiePos + 8);
const tocOff = buf.readUInt32BE(cookiePos + 12);
const tocLen = buf.readUInt32BE(cookiePos + 16);
const pyvers = buf.readUInt32BE(cookiePos + 20);
const archStart = cookiePos + 88 - pkgLen;
console.log('pyvers', pyvers, 'pkgLen', pkgLen, 'tocLen', tocLen);

// --- parse CArchive TOC ---
const toc = [];
let p = archStart + tocOff;
const tocEnd = p + tocLen;
while (p < tocEnd) {
  const entryLen = buf.readUInt32BE(p);
  const off = buf.readUInt32BE(p + 4);
  const clen = buf.readUInt32BE(p + 8);
  const ulen = buf.readUInt32BE(p + 12);
  const cflag = buf[p + 16];
  const type = String.fromCharCode(buf[p + 17]);
  let name = buf.subarray(p + 18, p + entryLen).toString('latin1');
  name = name.replace(/\0+$/, '');
  toc.push({ off, clen, ulen, cflag, type, name });
  p += entryLen;
}

// --- minimal marshal parser (enough for code objects & TOC) ---
function makeParser(b) {
  let pos = 0;
  const refs = [];
  function read(n) { const r = b.subarray(pos, pos + n); pos += n; return r; }
  function parse(flagRef) {
    let t = read(1)[0];
    const hasRef = (t & 0x80) !== 0;
    t &= 0x7f;
    const c = String.fromCharCode(t);
    let val;
    switch (c) {
      case '0': case 'N': val = null; break;          // NULL / None (approx)
      case 'F': val = false; break;
      case 'T': val = true; break;
      case 'i': val = read(4).readInt32LE(0); break;
      case 'I': { const v = read(8); val = Number(v.readBigInt64LE(0)); break; }
      case 'g': val = read(8).readDoubleLE(0); break;
      case 's': { const n = read(4).readInt32LE(0); val = read(n).toString('latin1'); break; }
      case 'u': case 'z': case 'Z': case 'a': { const n = read(c === 'u' ? 4 : 1)[c === 'u' ? 'readInt32LE' : 'readUInt8'](0); val = read(n).toString('utf8'); break; }
      case ')': case '(': { const n = read(c === ')' ? 1 : 4)[c === ')' ? 'readUInt8' : 'readInt32LE'](0); val = []; if (hasRef) refs.push(val); for (let i = 0; i < n; i++) val.push(parse(false)); break; }
      case '[': { const n = read(4).readInt32LE(0); val = []; if (hasRef) refs.push(val); for (let i = 0; i < n; i++) val.push(parse(false)); break; }
      case 'r': val = refs[read(4).readInt32LE(0)]; break;
      case 'c': { // code object (3.x)
        val = { __code: true };
        val.argcount = read(4).readInt32LE(0);
        val.posonlyargcount = read(4).readInt32LE(0);
        val.kwonlyargcount = read(4).readInt32LE(0);
        val.nlocals = read(4).readInt32LE(0);
        val.stacksize = read(4).readInt32LE(0);
        val.flags = read(4).readInt32LE(0);
        val.code = parse(false);       // bytes (as latin1 string via 's')
        val.consts = parse(false);
        val.names = parse(false);
        val.varnames = parse(false);
        val.freevars = parse(false);
        val.cellvars = parse(false);
        val.filename = parse(false);
        val.name = parse(false);
        val.firstlineno = read(4).readInt32LE(0);
        val.lnotab = parse(false);
        break;
      }
      default: throw new Error('marshal type ' + JSON.stringify(c) + ' at ' + pos);
    }
    return val;
  }
  return { parse: () => parse(false), pos: () => pos };
}

// --- find and parse the PYZ ---
const pyzEntry = toc.find(e => e.type === 'z' || e.name.includes('PYZ'));
console.log('PYZ entry:', pyzEntry.name, pyzEntry.clen, pyzEntry.ulen);
let pyz = buf.subarray(archStart + pyzEntry.off, archStart + pyzEntry.off + pyzEntry.clen);
if (pyzEntry.cflag) pyz = inflateSync(pyz);
console.log('PYZ magic:', pyz.subarray(0, 4).toString('latin1'), 'pycmagic:', pyz.subarray(4, 8).toString('hex'));
const pyzTocOff = pyz.readUInt32BE(8);
const pyzToc = makeParser(pyz.subarray(pyzTocOff)).parse();

for (const entry of pyzToc) {
  const [name, type, off, len] = entry;
  if (/sqlparse[/.](lexer|engine[/.]statement_splitter|__init__)/.test(String(name))) {
    const raw = pyz.subarray(off, off + len);
    const data = inflateSync(raw);
    console.log('\n===== MODULE', name, 'len', data.length, '=====');
    try {
      const code = makeParser(data).parse();
      // dump all string consts recursively
      const seen = new Set();
      function dump(co, depth) {
        if (!co || typeof co !== 'object') return;
        if (co.__code) {
          console.log(`${'  '.repeat(depth)}<code ${co.name} line ${co.firstlineno}>`);
          for (const cst of co.consts || []) {
            if (typeof cst === 'string') {
              const s = cst.length > 300 ? cst.slice(0, 300) + '…' : cst;
              if (!seen.has(cst)) { seen.add(cst); console.log(`${'  '.repeat(depth)}  const: ${JSON.stringify(s)}`); }
            } else if (cst && cst.__code) dump(cst, depth + 1);
            else if (Array.isArray(cst)) console.log(`${'  '.repeat(depth)}  tuple: ${JSON.stringify(cst)}`);
          }
        }
      }
      dump(code, 0);
    } catch (e) {
      console.log('marshal parse failed:', e.message, '— dumping raw strings');
      const strs = data.toString('latin1').match(/[\x20-\x7e]{4,}/g) || [];
      for (const s of strs) console.log('  raw:', JSON.stringify(s));
    }
  }
}

