import { readFileSync } from 'node:fs';

// Full-ish marshal parser for Python 3.12
function parser(b) {
  let pos = 0;
  const refs = [];
  const rd = n => { const r = b.subarray(pos, pos + n); pos += n; return r; };
  function parse() {
    let t = rd(1)[0];
    const flagRef = (t & 0x80) !== 0;
    t &= 0x7f;
    const c = String.fromCharCode(t);
    let val, n, i;
    switch (c) {
      case '0': return undefined;         // NULL (only as terminator)
      case 'N': return null;
      case 'F': return false;
      case 'T': return true;
      case '.': return '...';
      case 'i': return rd(4).readInt32LE(0);
      case 'I': { n = rd(4).readInt32LE(0); let v = 0n; const d = rd(Math.abs(n) * 2); for (let k = Math.abs(n) - 1; k >= 0; k--) v = (v << 15n) | BigInt(d.readUInt16LE(k * 2)); return n < 0 ? -v : v; }
      case 'g': return rd(8).readDoubleLE(0);
      case 'y': case 'x': { n = rd(8); const re = n.readDoubleLE(0), im = n.readDoubleLE(8); pos += 8; return `${re}${im < 0 ? '' : '+'}${im}j`; }
      case 's': n = rd(4).readInt32LE(0); val = { __bytes: rd(n).toString('latin1') }; break;
      case 'u': n = rd(4).readInt32LE(0); val = rd(n).toString('utf8'); break;
      case 'z': case 'Z': case 'a': case 'A': n = rd(1)[0]; val = rd(n).toString('utf8'); break;
      case ')': n = rd(1)[0]; val = []; if (flagRef) refs.push(val); for (i = 0; i < n; i++) val.push(parse()); return val;
      case '(': n = rd(4).readInt32LE(0); val = []; if (flagRef) refs.push(val); for (i = 0; i < n; i++) val.push(parse()); return val;
      case '[': n = rd(4).readInt32LE(0); val = []; if (flagRef) refs.push(val); for (i = 0; i < n; i++) val.push(parse()); return val;
      case '<': case '>': n = rd(4).readInt32LE(0); val = { __set: [] }; if (flagRef) refs.push(val); for (i = 0; i < n; i++) val.__set.push(parse()); return val;
      case '{': val = {}; if (flagRef) refs.push(val); for (;;) { const k = parse(); if (k === undefined) break; val[String(k)] = parse(); } return val;
      case 'r': return refs[rd(4).readInt32LE(0)];
      case 'c': {
        val = { __code: true };
        if (flagRef) refs.push(val);
        val.argcount = rd(4).readInt32LE(0);
        val.posonly = rd(4).readInt32LE(0);
        val.kwonly = rd(4).readInt32LE(0);
        val.stacksize = rd(4).readInt32LE(0);
        val.flags = rd(4).readInt32LE(0);
        val.code = parse();
        val.consts = parse();
        val.names = parse();
        val.localsplusnames = parse();
        val.localspluskinds = parse();
        val.filename = parse();
        val.name = parse();
        val.qualname = parse();
        val.firstlineno = rd(4).readInt32LE(0);
        val.linetable = parse();
        val.exceptiontable = parse();
        return val;
      }
      default: throw new Error('marshal type ' + JSON.stringify(c) + ' @' + pos);
    }
    if (flagRef) refs.push(val);
    return val;
  }
  return { parse, pos: () => pos };
}

function show(v) {
  if (v && v.__bytes !== undefined) return 'b' + JSON.stringify(v.__bytes.length > 120 ? v.__bytes.slice(0, 120) + '…' : v.__bytes);
  if (v && v.__set) return 'set' + JSON.stringify(v.__set.map(show));
  if (Array.isArray(v)) return '(' + v.map(show).join(', ') + ')';
  if (v && v.__code) return `<code ${v.name}>`;
  if (typeof v === 'string') return JSON.stringify(v.length > 200 ? v.slice(0, 200) + '…' : v);
  return String(v);
}

function dump(co, depth) {
  const pad = '  '.repeat(depth);
  console.log(`${pad}### code ${co.qualname || co.name} (line ${co.firstlineno})`);
  console.log(`${pad}  names: ${show(co.names)}`);
  console.log(`${pad}  locals: ${show(co.localsplusnames)}`);
  for (const cst of co.consts || []) {
    if (cst && cst.__code) continue;
    console.log(`${pad}  const: ${show(cst)}`);
  }
  if (co.code && co.code.__bytes) {
    writeCode(co);
  }
  for (const cst of co.consts || []) {
    if (cst && cst.__code) dump(cst, depth + 1);
  }
}

// 3.12 opcode table (subset, enough for reading logic)
const OPS = [];
const op = (n, name, hasArg = true) => { OPS[n] = { name, hasArg }; };
op(1, 'POP_TOP'); op(2, 'PUSH_NULL'); op(3, 'NOP'); op(4, 'UNARY_POSITIVE'); op(5, 'UNARY_NEGATIVE');
op(6, 'UNARY_NOT'); op(9, 'UNARY_INVERT'); op(25, 'BINARY_SUBSCR'); op(30, 'GET_LEN');
op(35, 'MATCH_MAPPING'); op(36, 'MATCH_SEQUENCE'); op(37, 'MATCH_KEYS'); op(42, 'JUMP_BACKWARD_NO_INTERRUPT');
op(43, 'STORE_SUBSCR'); op(49, 'DELETE_SUBSCR'); op(55, 'GET_AITER'); op(56, 'GET_ANEXT');
op(68, 'GET_ITER'); op(73, 'LOAD_BUILD_CLASS'); op(74, 'LOAD_ASSERTION_ERROR'); op(75, 'RETURN_GENERATOR');
op(76, 'BEFORE_WITH'); op(80, 'RETURN_CONST'); op(85, 'LIST_EXTEND'); op(86, 'SET_UPDATE');
op(87, 'DICT_MERGE'); op(88, 'DICT_UPDATE'); op(89, 'LOAD_LOCALS'); op(90, 'LOAD_FROM_DICT_OR_GLOBALS');
op(91, 'LOAD_FROM_DICT_OR_DEREF'); op(92, 'LOAD_NAME'); op(93, 'BUILD_TUPLE'); op(95, 'BUILD_LIST');
op(97, 'BUILD_MAP'); op(100, 'LOAD_ATTR'); op(101, 'COMPARE_OP'); op(102, 'IMPORT_NAME');
op(103, 'IMPORT_FROM'); op(106, 'JUMP_FORWARD'); op(107, 'POP_JUMP_IF_FALSE'); op(108, 'POP_JUMP_IF_TRUE');
op(109, 'LOAD_GLOBAL'); op(110, 'IS_OP'); op(111, 'CONTAINS_OP'); op(112, 'RERAISE');
op(113, 'COPY'); op(114, 'BINARY_OP'); op(115, 'SEND'); op(116, 'LOAD_FAST');
op(117, 'STORE_FAST'); op(118, 'DELETE_FAST'); op(119, 'LOAD_FAST_CHECK'); op(120, 'POP_JUMP_IF_NOT_NONE');
op(121, 'POP_JUMP_IF_NONE'); op(122, 'RAISE_VARARGS'); op(123, 'GET_AWAITABLE'); op(124, 'MAKE_FUNCTION');
op(125, 'BUILD_SLICE'); op(126, 'JUMP_BACKWARD'); op(127, 'LOAD_DEREF'); op(128, 'STORE_DEREF');
op(129, 'DELETE_DEREF'); op(130, 'CALL_FUNCTION_EX'); op(131, 'EXTENDED_ARG'); op(132, 'LIST_APPEND');
op(133, 'SET_ADD'); op(134, 'MAP_ADD'); op(135, 'LOAD_CLASSDEREF'); op(137, 'COPY_DICT_WITHOUT_KEYS');
op(138, 'GET_YIELD_FROM_ITER'); op(140, 'PRINT_EXPR'); op(141, 'LOAD_SUPER_ATTR'); op(142, 'LOAD_SUPER_ATTR');
op(143, 'LOAD_FAST_AND_CLEAR'); op(144, 'YIELD_VALUE'); op(145, 'RESUME'); op(146, 'MATCH_CLASS');
op(147, 'BUILD_CONST_KEY_MAP'); op(149, 'STORE_ATTR'); op(150, 'DELETE_ATTR'); op(151, 'STORE_GLOBAL');
op(152, 'DELETE_GLOBAL'); op(153, 'LOAD_CONST'); op(154, 'LOAD_NAME'); op(157, 'BUILD_STRING');
op(159, 'JUMP_IF_NOT_EXC_MATCH'); op(160, 'CHECK_EXC_MATCH'); op(162, 'BEFORE_ASYNC_WITH');
op(163, 'BEFORE_WITH'); op(164, 'END_ASYNC_FOR'); op(165, 'STORE_SUBSCR'); op(171, 'CALL');
op(172, 'KW_NAMES'); op(173, 'POP_JUMP_IF_FALSE'); op(174, 'POP_JUMP_IF_TRUE'); op(175, 'CONTINUE_LOOP');
op(181, 'WITH_EXCEPT_START'); op(187, 'LOAD_SMALL_INT'); op(189, 'HAS_ARG');
// generic fallbacks for common ones
const CMP = ['<', '<=', '==', '!=', '>', '>='];

function disasm(co) {
  const bytes = Buffer.from(co.code.__bytes, 'latin1');
  const lines = [];
  let ext = 0;
  for (let i = 0; i < bytes.length; i += 2) {
    const opc = bytes[i];
    const arg = bytes[i + 1] | ext;
    ext = opc === 131 ? (arg << 8) : 0;
    const e = OPS[opc];
    const name = e ? e.name : `OP${opc}`;
    let detail = '';
    if (name === 'LOAD_CONST' || name === 'RETURN_CONST') detail = show(co.consts[arg]);
    else if (['LOAD_GLOBAL', 'LOAD_NAME', 'IMPORT_NAME', 'LOAD_ATTR', 'STORE_ATTR', 'LOAD_METHOD'].includes(name)) detail = show(co.names[name === 'LOAD_GLOBAL' ? arg >> 1 : arg]) + (name === 'LOAD_GLOBAL' && (arg & 1) ? ' +NULL' : '');
