import { readFileSync } from 'node:fs';

function makeParser(b, opts) {
  let pos = 0;
  const refs = [];
  const rd = n => { const r = b.subarray(pos, pos + n); pos += n; return r; };
  function refPush(v, flag) { if (opts.reserveAlways || flag) refs.push(flag ? v : undefined); }
  function refPushLate(v, flag) { if (flag) refs.push(v); }
  function parse() {
    let t = rd(1)[0];
    const flagRef = (t & 0x80) !== 0;
    t &= 0x7f;
    const c = String.fromCharCode(t);
    let val, n;
    switch (c) {
      case '0': case 'N': return null;
      case 'F': return false;
      case 'T': return true;
      case 'i': return rd(4).readInt32LE(0);
      case 's': n = rd(4).readInt32LE(0); val = { __bytes: rd(n).toString('latin1') }; refPushLate(val, flagRef); return val;
      case 'u': case 'a': case 'A': n = rd(4).readInt32LE(0); val = rd(n).toString('utf8'); refPushLate(val, flagRef); return val;
      case 'z': case 'Z': n = rd(1)[0]; val = rd(n).toString('utf8'); refPushLate(val, flagRef); return val;
      case ')': n = rd(1)[0]; val = [];
        if (opts.containerBefore) refPush(val, flagRef);
        for (let i = 0; i < n; i++) val.push(parse());
        if (!opts.containerBefore) refPush(val, flagRef);
        return val;
      case '(': n = rd(4).readInt32LE(0); val = [];
        if (opts.containerBefore) refPush(val, flagRef);
        for (let i = 0; i < n; i++) val.push(parse());
        if (!opts.containerBefore) refPush(val, flagRef);
        return val;
      case '[': n = rd(4).readInt32LE(0); val = [];
        if (opts.containerBefore) refPush(val, flagRef);
        for (let i = 0; i < n; i++) val.push(parse());
        if (!opts.containerBefore) refPush(val, flagRef);
        return val;
      case '{': val = {};
        if (opts.containerBefore) refPush(val, flagRef);
        for (;;) { const k = parse(); if (k === undefined) break; val[String(k)] = parse(); }
        if (!opts.containerBefore) refPush(val, flagRef);
        return val;
      case 'r': return refs[rd(4).readInt32LE(0)];
      case 'c': {
        val = { __code: true };
        if (opts.codeBefore) { if (opts.codeAlways || flagRef) refs.push(flagRef || opts.codeAlways ? val : undefined); }
        val.argcount = rd(4).readInt32LE(0);
        val.posonly = rd(4).readInt32LE(0);
        val.kwonly = rd(4).readInt32LE(0);
        val.stacksize = rd(4).readInt32LE(0);
        val.flags = rd(4).readInt32LE(0);
        val.code = parse();
        val.consts = parse();
        val.names = parse();
        val.localsplusnames = parse();
        val.localspluskinds = parse();
        val.filename = parse();
        val.name = parse();
        val.qualname = parse();
        val.firstlineno = rd(4).readInt32LE(0);
        val.linetable = parse();
        val.exceptiontable = parse();
        if (!opts.codeBefore) { if (flagRef) refs.push(val); }
        return val;
      }
      default: throw new Error('type ' + JSON.stringify(c) + ' @' + pos);
    }
  }
  return { parse, pos: () => pos };
}

function validate(co, errs) {
  if (!co || !co.__code) return;
  for (const field of ['names', 'localsplusnames']) {
    const t = co[field];
    if (!Array.isArray(t)) { errs.push(`${co.name}: ${field} not tuple`); continue; }
    for (const e of t) if (typeof e !== 'string') { errs.push(`${co.name}: ${field} has non-string`); break; }
  }
  if (typeof co.filename !== 'string') errs.push(`${co.name}: bad filename`);
  if (typeof co.name !== 'string') errs.push(`${co.name}: bad name`);
  for (const c of co.consts || []) if (c && c.__code) validate(c, errs);
}

const data = readFileSync(process.argv[2]);
for (const containerBefore of [true, false])
  for (const codeBefore of [true, false])
    for (const reserveAlways of [true, false])
      for (const codeAlways of [true, false]) {
        const opts = { containerBefore, codeBefore, reserveAlways, codeAlways };
        try {
          const p = makeParser(data, opts);
          const co = p.parse();
          const errs = [];
          validate(co, errs);
          const tag = JSON.stringify(opts);
          if (errs.length === 0 && p.pos() === data.length) console.log('PERFECT', tag);
          else console.log('fail', tag, errs.slice(0, 2), 'pos', p.pos(), '/', data.length);
        } catch (e) {
          console.log('throw', JSON.stringify(opts), e.message);
        }
      }

// Python 3.12 disassembler for the anchored opcode subset; unknowns shown raw.
import { readFileSync } from 'node:fs';

const OPS = {
  0: 'CACHE', 1: 'POP_TOP', 2: 'PUSH_NULL', 4: 'END_FOR', 5: 'UNARY_POSITIVE',
  6: 'UNARY_NEGATIVE', 7: 'UNARY_NOT', 11: 'BINARY_SUBSCR?', 68: 'GET_ITER',
  75: 'RETURN_GENERATOR', 90: 'STORE_NAME', 92: 'UNPACK_SEQUENCE', 93: 'FOR_ITER',
  95: 'STORE_ATTR', 100: 'LOAD_CONST', 101: 'IMPORT_NAME?', 102: 'BUILD_TUPLE',
  106: 'LOAD_ATTR', 107: 'COMPARE_OP', 108: 'IMPORT_NAME', 109: 'IMPORT_FROM',
  114: 'POP_JUMP_IF_FALSE', 115: 'POP_JUMP_IF_TRUE', 116: 'LOAD_GLOBAL',
  117: 'IS_OP', 118: 'CONTAINS_OP', 121: 'RETURN_CONST', 124: 'LOAD_FAST',
  125: 'STORE_FAST', 132: 'MAKE_FUNCTION', 140: 'JUMP_BACKWARD',
  144: 'JUMP_BACKWARD_NO_INTERRUPT', 150: 'YIELD_VALUE', 151: 'RESUME', 171: 'CALL',
};
const CMP = ['<', '<=', '==', '!=', '>', '>='];

// co_code extracted manually from dump (hex)
const targets = {
  _change_splitlevel: {
    hex: '',
    consts: ['doc', '(', 1, ')', -1, 0, 'CREATE', true, 'DECLARE', 'BEGIN',
      ['TRANSACTION', 'WORK', 'TRAN', 'DISTRIBUTED', 'DEFERRED', 'IMMEDIATE', 'EXCLUSIVE'],
      false, 'END', ['IF', 'FOR', 'WHILE', 'CASE'], null, ['END IF', 'END FOR', 'END WHILE']],
    names: ['T', 'Punctuation', 'Keyword', 'upper', 'DDL', 'startswith', '_begin_depth',
      '_seen_begin', '_in_case', 'consume_ws', 'Name', 'max', '_is_create'],
    locals: ['self', 'ttype', 'value', 'unified'],
  },
};

function disasm(t) {
  const b = Buffer.from(t.hex, 'hex');
  let i = 0;
  while (i < b.length) {
    const start = i;
    const opc = b[i];
    const arg = b[i + 1];
    i += 2;
    const name = OPS[opc] || `OP${opc}`;
    let detail = '';
    if (name === 'LOAD_CONST' || name === 'RETURN_CONST') detail = JSON.stringify(t.consts[arg]);
    else if (name === 'LOAD_GLOBAL') detail = t.names[arg >> 1] + ((arg & 1) ? ' (+null)' : '');
    else if (name === 'LOAD_ATTR') detail = '.' + t.names[arg >> 1] + ((arg & 1) ? ' (+null)' : '');
    else if (name === 'STORE_ATTR') detail = '.' + t.names[arg];
    else if (name === 'LOAD_FAST' || name === 'STORE_FAST') detail = t.locals[arg];
    else if (name === 'COMPARE_OP') detail = CMP[arg >> 4] + ` (raw ${arg})`;
    else if (name === 'CONTAINS_OP') detail = arg ? 'not in' : 'in';
    else if (name === 'IS_OP') detail = arg ? 'is not' : 'is';
    else if (name === 'POP_JUMP_IF_FALSE' || name === 'POP_JUMP_IF_TRUE' || name === 'FOR_ITER' || name === 'JUMP_BACKWARD' || name === 'JUMP_BACKWARD_NO_INTERRUPT') detail = '->' + (name.startsWith('JUMP_BACK') ? start + 2 - arg * 2 : start + 2 + arg * 2);
    else detail = String(arg);
    console.log(String(start).padStart(4), name.padStart(28), detail);
    // skip inline caches: count zero-word runs that belong to known ops
    const caches = { LOAD_GLOBAL: 4, LOAD_ATTR: 9, STORE_ATTR: 4, COMPARE_OP: 1, CALL: 3, LOAD_FAST: 0, UNPACK_SEQUENCE: 1, FOR_ITER: 1 }[name] || 0;
    let skipped = 0;
    while (skipped < caches * 2 && b[i] === 0 && b[i + 1] === 0) { i += 2; skipped += 2; }
  }
}

disasm(targets._change_splitlevel);
